    const H = HAARE[m.haar];
    const teile2 = [];
    if (opt.hintergrund) teile2.push(`<rect width="100" height="100" fill="${opt.hintergrund}"/>`);
    const umriss = ` stroke="${dunkel2(hf, 0.35)}" stroke-width="0.6" stroke-linejoin="round"`;
    for (const [x2, y2, rr5] of H.wolke ?? []) teile2.push(`<circle cx="${x2}" cy="${y2}" r="${rr5}" fill="${hf}"${umriss}/>`);
    for (const [x2, y2, rr5] of H.wolke ?? []) teile2.push(`<circle cx="${x2}" cy="${y2}" r="${rr5 - 0.4}" fill="${hf}"/>`);
    if (H.hinten) teile2.push(P2(H.hinten, dunkel2(hf, 0.1), umriss));
