    ball: () => `<circle r="10" fill="#fbf7ee" stroke="#2a2c30" stroke-width="0.8"/><path d="${sternPfad(4.2, 0.81)}" fill="#2a2c30"/>` + [0, 1, 2, 3, 4].map((i) => `<path d="M${f11(4.2 * Math.cos(i * 1.2566 - 1.57))} ${f11(4.2 * Math.sin(i * 1.2566 - 1.57))} L${f11(9.6 * Math.cos(i * 1.2566 - 1.57))} ${f11(9.6 * Math.sin(i * 1.2566 - 1.57))}" stroke="#2a2c30" stroke-width="0.8"/>`).join(""),
    anker: () => `<g fill="none" stroke="${KANTE2}" stroke-width="3.6" stroke-linecap="round"><path d="M0 -8 V9 M-5 -4 H5 M-9 3 Q0 14 9 3"/><circle cx="0" cy="-10" r="2.4"/></g><g fill="none" stroke="#c8372f" stroke-width="1.8" stroke-linecap="round"><path d="M0 -8 V9 M-5 -4 H5 M-9 3 Q0 14 9 3"/><circle cx="0" cy="-10" r="2.4"/></g>`,
